DROP TABLE IF EXISTS `laporan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `laporan` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tracking_id` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sekolah_npsn` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fasilitas_terkait` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kondisi_dilaporkan` enum('baik','rusak_ringan','rusak_sedang','rusak_berat') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deskripsi` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `klaster_id` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status_sanggahan` enum('menunggu','divalidasi','ditolak') COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_laporan_tracking_id` (`tracking_id`),
  KEY `klaster_id` (`klaster_id`),
  KEY `sekolah_npsn` (`sekolah_npsn`),
