  CONSTRAINT `laporan_ibfk_1` FOREIGN KEY (`klaster_id`) REFERENCES `klaster` (`id`),
  CONSTRAINT `laporan_ibfk_2` FOREIGN KEY (`sekolah_npsn`) REFERENCES `sekolah` (`npsn`),
  CONSTRAINT `laporan_ibfk_3` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
