  KEY `klaster_id` (`klaster_id`),
  CONSTRAINT `status_log_ibfk_1` FOREIGN KEY (`actor_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `status_log_ibfk_2` FOREIGN KEY (`klaster_id`) REFERENCES `klaster` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
